import{_ as t,l as n,o,c as i,v as a,p as s,x as l,d as h,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"VERLTool","description":"","frontmatter":{"title":"VERLTool","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/verltool.md","filePath":"llm/verltool.md","lastUpdated":1789023840000}'),p={name:"llm/verltool.md"};function L(R,e,A,T,m,g){const r=n("Mermaid");return o(),i("div",null,[e[1]||(e[1]=a('<h1 id="verltool" tabindex="-1">VERLTool <a class="header-anchor" href="#verltool" aria-label="Permalink to &quot;VERLTool&quot;">​</a></h1><div class="epigraph"><p>把 RL 工作流和工具执行拆开：训练继续跟上游 VeRL，工具走独立服务器上的标准 API，轨迹按条异步跑，而不是整批在工具调用上对齐等待。</p><footer>—— Jiang 等，VerlTool: Towards Holistic Agentic Reinforcement Learning with Tool Use，arXiv:2509.01055</footer></div><p><a href="/llm/rlvr">RLVR</a> 把可验证标量接进策略梯度，但默认仍是单轮：模型写完，验证器看终点，没有环境。一旦允许模型调代码、检索、SQL 或视觉算子，轨迹变成多轮，观察 token 来自工具而不是策略，系统还要在工具延迟上排队。TIGER-AI-Lab 的 <strong>VerlTool</strong>（Jiang、Lu 等，arXiv:2509.01055，仓库 <code>TIGER-AI-Lab/verl-tool</code>）把这件事命名为 <strong>ARLT</strong>（Agentic Reinforcement Learning with Tool use），并做成跟 VeRL 子模块对齐的插件层。本篇钉四条贡献怎么读：上游对齐、统一工具服务、异步 rollout 的近 2×、以及六个领域的「能用同一套基建追上专用仓库」。不把 ARLT 写成新的优势估计——损失仍是 PPO / GRPO 家族，变的是轨迹与掩码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Search-R1、Pixel-Reasoner、各类代码 RL 往往各写一份环境循环，工具协议写死，VeRL 一升级就分叉。同步 rollout 按 batch 对齐：一条样本还在等 Python 解释器，整批 GPU 空转。多模态工具会返回图像或视频 token，文本-only 的拼接假设崩溃。Jiang 等人把碎片化、同步气泡、跨域难扩展列为社区采用的三块石头。</p><p>概念上，单轮 RLVR 的状态是提示加已生成前缀；ARLT 的状态还包含环境与工具会话。动作是模型 token（常含 tool call），观察是工具返回，再经模板写回上下文。形式化后，轨迹是多轮、可多模态观察的序列。这要求训练侧能区分「该反传的模型 token」和「只做条件、不进策略损失的观察」，见 <a href="/llm/multiturn-loss-mask">多轮 loss mask</a>。</p><h3 id="表-1-不是排行榜" tabindex="-1">表 1 不是排行榜 <a class="header-anchor" href="#表-1-不是排行榜" aria-label="Permalink to &quot;表 1 不是排行榜&quot;">​</a></h3><p>论文用一张工具覆盖表对照 OpenRLHF、VeRL、ROLL、RAGEN、slime、AReaL、SkyRL：检索、Python、Web、Bash、SQL、图像。VerlTool 六列都打勾。这是 2025 年 8 月 23 日截止的功能矩阵，不是吞吐或准确率排名。SkyRL 也覆盖终端与 SQL，但作者批评容器化部署重。缺勾的框架不代表不能接工具，只代表当时主仓库没有统一服务器。引用时写日期，避免用过期表格打后来的 slime / AReaL 版本。</p><p><span class="marginnote">VeRL 以 git submodule 接入。好处是跟 Sheng 等 HybridFlow 上游同步；坏处是你的插件必须跟 VeRL 的 DataProto / AgentLoop 契约一起变。这是维护策略，不是「我们 fork 后更稳」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>架构拆成 <strong>RL workflow</strong>（VeRL 的训练、优势、更新）和 <strong>Tool Server</strong>（独立进程，标准交互 API）。Actor 在轨迹级与工具服务器通信，而不是「整个 micro-batch 一起 call_tool」。新工具是一个 Python 类：实现解析、执行、返回 observation。启动例：<code>python -m verl_tool.servers.serve --tool_type python_code --workers_per_tool 4</code>。无效动作可配 <code>done_if_invalid</code>；<code>finish</code> 工具负责清环境状态。</p><p>异步 rollout：各轨迹自己的工具延迟不再阻塞同批其他请求，论文报消除同步等待后 rollout 近 <strong>2×</strong>。这与 <a href="/llm/areal-async-rl">AReaL</a> 的「训练–生成分池」不同：VerlTool 的 2× 主要来自<strong>工具等待</strong>，即使训练仍按 PPO 步同步，只要同一步内多轨迹不在工具上对齐，墙钟就会掉下来。六个任务：数学（代码执行）、知识 QA（检索）、SQL、视觉推理、网页搜索、软件工程（SWE-Bench 类），声称与专用系统可比，但统一在一套训练基础设施上。</p>',12)),(o(),s(d,null,{default:l(()=>[c(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20VE%5B%22VeRL%20%E8%AE%AD%E7%BB%83%E7%8E%AF%22%5D%20--%3E%20AL%5B%22Agent%20%2F%20Rollout%22%5D%0A%20%20AL%20--%3E%7C%22tool%20call%22%7C%20TS%5B%22Tool%20Server%22%5D%0A%20%20TS%20--%3E%20PY%5B%22Python%20%2F%20SQL%20%2F%20Bash%22%5D%0A%20%20TS%20--%3E%20SR%5B%22Search%20%2F%20Web%22%5D%0A%20%20TS%20--%3E%20VI%5B%22%E8%A7%86%E8%A7%89%E7%AE%97%E5%AD%90%22%5D%0A%20%20TS%20--%3E%7C%22observation%20tokens%22%7C%20AL%0A%20%20AL%20--%3E%7C%22masked%20%E8%BD%A8%E8%BF%B9%22%7C%20VE%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="插件只解决注册-不解决奖励" tabindex="-1">插件只解决注册，不解决奖励 <a class="header-anchor" href="#插件只解决注册-不解决奖励" aria-label="Permalink to &quot;插件只解决注册，不解决奖励&quot;">​</a></h3><p>加一个 Python 文件能让轨迹跑通，不能告诉你 \\(r\\) 怎么定义。SQL 任务的奖励可能是执行结果匹配；SWE 可能是测试通过率；搜索可能是答案 EM。ARLT 的「整体」指工具与多轮循环进同一框架，不是一个万能奖励。每个域仍要自己的验证器与数据清洗，否则 GRPO 只是在过拟合格式化的 tool call。</p><p><span class="marginnote">作者列表以 Jiang 为项目负责人，bibtex 作 Jiang et al. 2025，arXiv:2509.01055。代码 <a href="https://github.com/TIGER-AI-Lab/verl-tool%E3%80%82%E5%AF%B9%E7%85%A7" target="_blank" rel="noreferrer">https://github.com/TIGER-AI-Lab/verl-tool。对照</a> HybridFlow / verl：Sheng 等 arXiv:2409.19256。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>上游对齐把「怎么切 DP/TP、怎么重切分 actor」留给 VeRL，VerlTool 只拥有环境边。这与 <a href="/llm/agent-lightning">Agent Lightning</a> 的「harness 完全在训练外」不同：VerlTool 仍假设你在 VeRL 的 agent 循环里发 tool call，只是执行被卸到服务器。Lightning 连循环所有权都交给外部 harness。两者都要处理观察 token，但控制面不同。</p><p>异步的收益随工具时间占比上升。纯数学、验证器是正则匹配、几乎无 I/O 时，2× 不会出现。解释器冷启动、检索 RTT、浏览器，收益才大。服务器 <code>workers_per_tool</code> 过小会把气泡从 GPU 挪到工具进程队列；过大则打爆沙箱。多模态观察必须进入 tokenizer 的约定位置，并在 mask 上标 0，否则策略会学着模仿检索片段的文风。</p><h3 id="与单轮-rlvr-的梯度差异" tabindex="-1">与单轮 RLVR 的梯度差异 <a class="header-anchor" href="#与单轮-rlvr-的梯度差异" aria-label="Permalink to &quot;与单轮 RLVR 的梯度差异&quot;">​</a></h3><p>单轮里每个 token 的优势通常来自终点标量广播。多轮工具里，中间错误调用仍可能被终点成功掩盖（偶然搜到答案）。组相对基线能减方差，但不能替代过程奖励。VerlTool 提供轨迹结构，不强制 PRM。若你把工具失败写成负过程分，要自己接进奖励函数，并保证 mask 仍不在观察上反传。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把六个域的「可比」写成全面 SOTA；专用仓库往往有未迁移的数据增强。不要在同步 VeRL 配置下期望论文的 2×。工具沙箱的安全与隔离是运维问题：Python 执行器等于在训练集群跑任意代码。VeRL 子模块升级可能改 AgentLoop API，插件要跟着改。若团队的 agent 已经在 LangChain 里写死、不愿重写成 Tool Server 类，Agent Lightning 的代理端点更合适。</p><p>SWE 与浏览任务的墙钟由环境主导，框架加速有上限。先 profile 工具 RTT，再决定值不值得上异步。沙箱失败（超时、OOM、网络策略）应返回可解析的错误观察并结束轨迹，而不是让 rollout 挂起；否则异步队列会被坏环境拖成同步。奖励函数必须能区分「工具崩溃」和「模型用错工具」，前者是系统噪声，后者才是策略该学的负信号。</p><p><span class="marginnote">Search-R1、ToolFormer（Schick 等）、OpenHands 是工具使用的前序，不是 VerlTool 的基线数字来源。引用 ARLT 时与 RLVR 分开：后者是奖励来源，前者是多轮工具交互范式。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VerlTool 在 VeRL 上拆出工具服务器，用标准 API 接代码、检索、SQL、视觉等，轨迹级异步减少工具对齐等待。</li><li>ARLT 把单轮 RLVR 扩成带观察 token 的多轮轨迹，损失掩码必须把工具输出排除出策略梯度。</li><li>近 2× 钉在 rollout/工具等待设定；六域实验证明统一基建可行，不是一张总榜。</li><li>出处：arXiv:2509.01055；<a href="https://github.com/TIGER-AI-Lab/verl-tool%E3%80%82" target="_blank" rel="noreferrer">https://github.com/TIGER-AI-Lab/verl-tool。</a></li></ul>',14))])}const E=t(p,[["render",L]]);export{_ as __pageData,E as default};
